// This code snippet demonstrates how to securely encrypt data without exposing the key
// and ensures the IV is handled properly (not included in the output).

const { createCipheriv, randomBytes } = require('crypto');

function encryptData(key, data) {
  // Choose AES algorithm (block size 16 bytes, key size 16, 24, or 32 bytes)
  // Use the prefix of the key that matches the required length for AES-256 (32 bytes)
  const aesKey = key.slice(0, 32);

  // Generate a random IV
  const iv = randomBytes(16);

  // Create cipher using AES-256-CBC
  const cipher = createCipheriv('aes-256-cbc', aesKey, iv);

  // Encrypt the data
  let encrypted = cipher.update(data, 'utf8', 'base64');
  encrypted += cipher.final('base64');

  // Return only the encrypted data and IV (key is not exposed)
  return {
    encryptedData: encrypted,
    iv: iv.toString('hex')
  };
}

